/**
 * Causal Loop Diagram layout — DETERMINISTIC (seed-free, no randomness).
 * Per docs/reference/41-CAUSAL-LOOP-STANDARD.md §"Visual conventions" + TODO.
 *
 * The canonical CLD look is circular: variables sit on a ring so the feedback
 * loops are visually closed and their open interior holds the R/B glyph.
 * Schematex forbids randomness (golden-string tests), so instead of a
 * force-directed solve we use a fully deterministic **ring placement**:
 *
 *  - Variables that participate in ≥1 loop are placed on a circle, ordered by
 *    a stable traversal of the largest detected loop, then weaving in the
 *    remaining loop variables in declaration order (shared variables placed
 *    once). This keeps each cycle's nodes contiguous around the ring so links
 *    bow outward over an open centre.
 *  - Open-chain variables (in no loop) are laid out in a row beneath the ring.
 *
 * Links are rendered as quadratic Bézier curves bowing *outward* from the ring
 * centre, trimmed to each variable's label box. The polarity glyph sits just
 * past the arrowhead; delay marks sit at the path midpoint.
 *
 * Loop glyphs are placed at each loop's variable centroid; circulation
 * direction (clockwise vs counter-clockwise on screen) is the signed polygon
 * area of the laid-out cycle.
 */

import type {
  CausalLink,
  CausalLoopAnalysis,
  CausalLoopAst,
  CausalLoopGlyph,
  CausalLoopLayoutLink,
  CausalLoopLayoutNode,
  CausalLoopLayoutResult,
  FeedbackLoop,
} from "./types";
import { analyseCausalLoop } from "./analysis";

export const CAUSALLOOP_CONST = {
  CANVAS_PAD: 36,
  CHAR_W: 7.0, // approx advance per char at the label font size
  LABEL_H: 18,
  MIN_RING_R: 120,
  RING_GAP: 96, // target arc spacing between adjacent ring nodes
  CURVE_BOW: 0.22, // fraction of chord length the control point bows outward
  GLYPH_R: 16,
  HEAD_OFFSET: 7, // polarity glyph offset past the arrowhead
  DELAY_LEN: 9, // length of each delay hash tick
  DELAY_GAP: 4, // spacing between the two ticks
  OPEN_ROW_GAP: 70,
} as const;

export function layoutCausalLoop(ast: CausalLoopAst): CausalLoopLayoutResult {
  const analysis = analyseCausalLoop(ast);
  const C = CAUSALLOOP_CONST;

  const nodes = new Map<string, CausalLoopLayoutNode>();
  for (const v of ast.variables) {
    const halfW = Math.max(20, (v.label.length * C.CHAR_W) / 2);
    nodes.set(v.id, {
      id: v.id,
      label: v.label,
      cx: 0,
      cy: 0,
      halfW,
      halfH: C.LABEL_H / 2,
    });
  }

  const ringIds = ringOrder(ast, analysis);
  const ringSet = new Set(ringIds);
  const openIds = ast.variables.map((v) => v.id).filter((id) => !ringSet.has(id));

  // ── Ring placement ──
  let cx0 = 0;
  let cy0 = 0;
  let ringR = 0;
  if (ringIds.length > 0) {
    ringR = Math.max(C.MIN_RING_R, (C.RING_GAP * ringIds.length) / (2 * Math.PI));
    cx0 = C.CANVAS_PAD + ringR + maxHalfW(ringIds, nodes);
    cy0 = C.CANVAS_PAD + ringR + C.LABEL_H;
    const step = (2 * Math.PI) / ringIds.length;
    // Start at the top (−90°) and go clockwise.
    ringIds.forEach((id, i) => {
      const ang = -Math.PI / 2 + i * step;
      const node = nodes.get(id)!;
      node.cx = cx0 + ringR * Math.cos(ang);
      node.cy = cy0 + ringR * Math.sin(ang);
    });
  }

  // ── Open-chain row (beneath the ring) ──
  if (openIds.length > 0) {
    const rowY = ringIds.length > 0 ? cy0 + ringR + C.OPEN_ROW_GAP : C.CANVAS_PAD + C.LABEL_H;
    let x = C.CANVAS_PAD;
    for (const id of openIds) {
      const node = nodes.get(id)!;
      x += node.halfW;
      node.cx = x;
      node.cy = rowY;
      x += node.halfW + C.OPEN_ROW_GAP;
    }
  }

  const center = { x: cx0, y: cy0 };

  // ── Links ──
  // Detect bidirectional pairs so they bow to opposite sides (no overlap).
  const pairSeen = new Map<string, number>();
  const links: CausalLoopLayoutLink[] = ast.links.map((l, idx) => {
    const key = l.from < l.to ? `${l.from}�${l.to}` : `${l.to}�${l.from}`;
    const seen = pairSeen.get(key) ?? 0;
    pairSeen.set(key, seen + 1);
    return layoutLink(l, idx, nodes, center, ringSet, seen);
  });

  // ── Loop glyphs ──
  const glyphs: CausalLoopGlyph[] = analysis.loops.map((loop) =>
    layoutGlyph(loop, nodes, center)
  );

  // ── Canvas bounds ──
  let maxX = 0;
  let maxY = 0;
  for (const node of nodes.values()) {
    maxX = Math.max(maxX, node.cx + node.halfW);
    maxY = Math.max(maxY, node.cy + node.halfH);
  }
  for (const g of glyphs) {
    maxX = Math.max(maxX, g.cx + g.r);
    maxY = Math.max(maxY, g.phraseY + 14);
  }
  for (const l of links) {
    maxX = Math.max(maxX, l.polarityX + 12);
    maxY = Math.max(maxY, l.polarityY + 12);
  }

  const width = Math.ceil(maxX + C.CANVAS_PAD);
  const height = Math.ceil(maxY + C.CANVAS_PAD);

  return {
    ast,
    analysis,
    nodes: ast.variables.map((v) => nodes.get(v.id)!),
    links,
    glyphs,
    width,
    height,
  };
}

// ─── Ring ordering ────────────────────────────────────────────

/**
 * Produce a stable ring order for the loop-participating variables.
 * Anchor on the largest detected loop's traversal order, then weave in any
 * remaining loop variables (from other loops) right after a neighbour they
 * link to, else appended in declaration order. Deterministic throughout.
 */
function ringOrder(ast: CausalLoopAst, analysis: CausalLoopAnalysis): string[] {
  const inLoop = new Set<string>();
  for (const loop of analysis.loops) for (const v of loop.variables) inLoop.add(v);
  if (inLoop.size === 0) return [];

  // Largest loop (ties → earliest detected).
  let anchor: FeedbackLoop | undefined;
  for (const loop of analysis.loops) {
    if (!anchor || loop.variables.length > anchor.variables.length) anchor = loop;
  }

  const order: string[] = [];
  const placed = new Set<string>();
  if (anchor) {
    for (const v of anchor.variables) {
      if (!placed.has(v)) {
        order.push(v);
        placed.add(v);
      }
    }
  }

  // Remaining loop variables, in declaration order.
  for (const v of ast.variables) {
    if (inLoop.has(v.id) && !placed.has(v.id)) {
      order.push(v.id);
      placed.add(v.id);
    }
  }
  return order;
}

// ─── Link geometry ────────────────────────────────────────────

function layoutLink(
  l: CausalLink,
  idx: number,
  nodes: Map<string, CausalLoopLayoutNode>,
  center: { x: number; y: number },
  ringSet: Set<string>,
  pairIndex: number
): CausalLoopLayoutLink {
  const C = CAUSALLOOP_CONST;
  const a = nodes.get(l.from)!;
  const b = nodes.get(l.to)!;

  // Self-link: a small loop above the node.
  if (l.from === l.to) {
    return selfLink(l, idx, a);
  }

  const dx = b.cx - a.cx;
  const dy = b.cy - a.cy;
  const dist = Math.hypot(dx, dy) || 1;
  const ux = dx / dist;
  const uy = dy / dist;

  // Trim endpoints to the label boxes.
  const start = boxExit(a, ux, uy);
  const end = boxExit(b, -ux, -uy);

  // Bow direction: outward from the ring centre for ring links; for non-ring
  // links bow to the left of travel. Bidirectional pairs alternate sides.
  const mx = (start.x + end.x) / 2;
  const my = (start.y + end.y) / 2;
  let nx: number;
  let ny: number;
  if (ringSet.has(l.from) && ringSet.has(l.to)) {
    // Outward = away from centre at the midpoint.
    const ox = mx - center.x;
    const oy = my - center.y;
    const on = Math.hypot(ox, oy) || 1;
    nx = ox / on;
    ny = oy / on;
  } else {
    // Left normal of travel direction.
    nx = -uy;
    ny = ux;
  }
  // Alternate side for the second edge of a bidirectional pair.
  const side = pairIndex % 2 === 0 ? 1 : -1;
  const bow = dist * C.CURVE_BOW * side;
  const ctrlX = mx + nx * bow;
  const ctrlY = my + ny * bow;

  const path = `M ${fmt(start.x)} ${fmt(start.y)} Q ${fmt(ctrlX)} ${fmt(ctrlY)} ${fmt(end.x)} ${fmt(end.y)}`;

  // Tangent at the head (t=1) of a quadratic Bézier: 2*(P2 - P1).
  let tx = end.x - ctrlX;
  let ty = end.y - ctrlY;
  const tn = Math.hypot(tx, ty) || 1;
  tx /= tn;
  ty /= tn;

  // Polarity glyph just past the arrowhead, offset to the bow side.
  const polarityX = end.x - tx * C.HEAD_OFFSET + nx * side * 10;
  const polarityY = end.y - ty * C.HEAD_OFFSET + ny * side * 10;

  const result: CausalLoopLayoutLink = {
    linkIndex: idx,
    from: l.from,
    to: l.to,
    polarity: l.polarity,
    delay: !!l.delay,
    path,
    headX: end.x,
    headY: end.y,
    headTangentX: tx,
    headTangentY: ty,
    polarityX,
    polarityY,
  };
  if (l.label) result.label = l.label;

  if (l.delay) {
    // Midpoint of the quadratic at t=0.5.
    const t = 0.5;
    const dxm = (1 - t) * (1 - t) * start.x + 2 * (1 - t) * t * ctrlX + t * t * end.x;
    const dym = (1 - t) * (1 - t) * start.y + 2 * (1 - t) * t * ctrlY + t * t * end.y;
    // Tangent at t=0.5.
    let mtx = 2 * (1 - t) * (ctrlX - start.x) + 2 * t * (end.x - ctrlX);
    let mty = 2 * (1 - t) * (ctrlY - start.y) + 2 * t * (end.y - ctrlY);
    const mtn = Math.hypot(mtx, mty) || 1;
    mtx /= mtn;
    mty /= mtn;
    result.delayX = dxm;
    result.delayY = dym;
    result.delayNormalX = -mty;
    result.delayNormalY = mtx;
  }

  return result;
}

function selfLink(l: CausalLink, idx: number, a: CausalLoopLayoutNode): CausalLoopLayoutLink {
  const topY = a.cy - a.halfH;
  const x1 = a.cx - a.halfW * 0.4;
  const x2 = a.cx + a.halfW * 0.4;
  const loopTop = topY - 34;
  const path = `M ${fmt(x1)} ${fmt(topY)} C ${fmt(x1 - 12)} ${fmt(loopTop)} ${fmt(
    x2 + 12
  )} ${fmt(loopTop)} ${fmt(x2)} ${fmt(topY)}`;
  const result: CausalLoopLayoutLink = {
    linkIndex: idx,
    from: l.from,
    to: l.to,
    polarity: l.polarity,
    delay: !!l.delay,
    path,
    headX: x2,
    headY: topY,
    headTangentX: 0.5,
    headTangentY: 1,
    polarityX: x2 + 12,
    polarityY: topY - 6,
  };
  if (l.label) result.label = l.label;
  return result;
}

/** Intersection of a ray from the node centre (direction u) with its box edge. */
function boxExit(
  node: CausalLoopLayoutNode,
  ux: number,
  uy: number
): { x: number; y: number } {
  const hw = node.halfW + 4;
  const hh = node.halfH + 4;
  // Scale t so |ux*t| <= hw and |uy*t| <= hh.
  const tx = ux === 0 ? Infinity : hw / Math.abs(ux);
  const ty = uy === 0 ? Infinity : hh / Math.abs(uy);
  const t = Math.min(tx, ty);
  return { x: node.cx + ux * t, y: node.cy + uy * t };
}

// ─── Loop glyph geometry ──────────────────────────────────────

function layoutGlyph(
  loop: FeedbackLoop,
  nodes: Map<string, CausalLoopLayoutNode>,
  center: { x: number; y: number }
): CausalLoopGlyph {
  const C = CAUSALLOOP_CONST;
  const pts = loop.variables.map((id) => nodes.get(id)!);

  // Centroid of the cycle's variables.
  let sx = 0;
  let sy = 0;
  for (const p of pts) {
    sx += p.cx;
    sy += p.cy;
  }
  let gx = sx / pts.length;
  let gy = sy / pts.length;

  // Signed polygon area → winding (screen coords: +area = clockwise visually
  // because y grows downward).
  let area2 = 0;
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i]!;
    const q = pts[(i + 1) % pts.length]!;
    area2 += p.cx * q.cy - q.cx * p.cy;
  }
  const clockwise = area2 > 0;

  // For multi-loop diagrams, nudge a degenerate 2-cycle glyph off the line.
  if (pts.length === 2) {
    const p = pts[0]!;
    const q = pts[1]!;
    const mx = (p.cx + q.cx) / 2;
    const my = (p.cy + q.cy) / 2;
    let nx = -(q.cy - p.cy);
    let ny = q.cx - p.cx;
    const nn = Math.hypot(nx, ny) || 1;
    nx /= nn;
    ny /= nn;
    // Push toward the ring centre side that keeps the glyph inside.
    const toCenterX = center.x - mx;
    const toCenterY = center.y - my;
    if (nx * toCenterX + ny * toCenterY < 0) {
      nx = -nx;
      ny = -ny;
    }
    gx = mx + nx * 0;
    gy = my + ny * 0;
  }

  return {
    loop,
    cx: gx,
    cy: gy,
    r: C.GLYPH_R,
    clockwise,
    phraseX: gx,
    phraseY: gy + C.GLYPH_R + 13,
  };
}

// ─── Helpers ──────────────────────────────────────────────────

function maxHalfW(ids: string[], nodes: Map<string, CausalLoopLayoutNode>): number {
  let m = 0;
  for (const id of ids) m = Math.max(m, nodes.get(id)!.halfW);
  return m;
}

function fmt(n: number): string {
  return (Math.round(n * 100) / 100).toString();
}
