/**
 * EPC layout — deterministic layered top-down process flow.
 * Per docs/reference/44-EPC-STANDARD.md §"Engine computation" (layout notes).
 *
 * Layering: longest-path from the start events (BFS over a back-edge-removed
 * DAG) assigns each node a rank; events and functions land on alternating ranks
 * with connectors interposed. Within a rank, nodes are ordered by a single
 * barycentre pass over the predecessor x-positions (stable, deterministic),
 * tie-broken by declaration order. Edges that would point *upward* (loops /
 * rework cycles) are detected as back-edges and routed around the right margin.
 *
 * `tb` (default) draws top-to-bottom; `lr` transposes axes. Zero deps.
 */

import type {
  EpcAst,
  EpcEdge,
  EpcLayoutEdge,
  EpcLayoutNode,
  EpcLayoutResult,
  EpcNode,
} from "./types";
import { analyseEpc } from "./analysis";

export const EPC_CONST = {
  EVENT_W: 150,
  EVENT_H: 54,
  FUNC_W: 160,
  FUNC_H: 64,
  CONN_R: 17,
  LAYER_GAP: 56, // vertical gap between rank bands
  NODE_GAP: 36, // horizontal gap between siblings in a rank
  CANVAS_PAD: 28,
  TITLE_H: 34,
  BACK_MARGIN: 60, // extra right margin for loop-back routing
} as const;

interface Sized {
  id: string;
  w: number;
  h: number;
}

export function layoutEpc(ast: EpcAst): EpcLayoutResult {
  const analysis = analyseEpc(ast);
  const byId = new Map<string, EpcNode>(ast.nodes.map((n) => [n.id, n] as const));

  // Node sizes.
  const sized = new Map<string, Sized>();
  for (const n of ast.nodes) sized.set(n.id, sizeOf(n));

  // Adjacency.
  const out = new Map<string, string[]>();
  const inn = new Map<string, string[]>();
  for (const n of ast.nodes) { out.set(n.id, []); inn.set(n.id, []); }
  for (const e of ast.edges) {
    if (!out.has(e.from) || !inn.has(e.to)) continue;
    out.get(e.from)!.push(e.to);
    inn.get(e.to)!.push(e.from);
  }

  // ── Back-edge detection (DFS) so layering works on a DAG ──
  const backEdges = detectBackEdges(ast, out);
  const backSet = new Set(backEdges.map((e) => `${e.from}�${e.to}`));
  const dagOut = new Map<string, string[]>();
  const dagIn = new Map<string, string[]>();
  for (const n of ast.nodes) { dagOut.set(n.id, []); dagIn.set(n.id, []); }
  for (const e of ast.edges) {
    if (backSet.has(`${e.from}�${e.to}`)) continue;
    if (!dagOut.has(e.from) || !dagIn.has(e.to)) continue;
    dagOut.get(e.from)!.push(e.to);
    dagIn.get(e.to)!.push(e.from);
  }

  // ── Longest-path layering over the DAG ──
  const layer = longestPathLayers(ast, dagOut, dagIn);

  // Group by layer.
  const maxLayer = Math.max(0, ...ast.nodes.map((n) => layer.get(n.id) ?? 0));
  const ranks: string[][] = Array.from({ length: maxLayer + 1 }, () => []);
  for (const n of ast.nodes) ranks[layer.get(n.id) ?? 0]!.push(n.id);

  // ── Ordering within ranks: barycentre over predecessor index ──
  orderRanks(ranks, dagIn, ast);

  // ── Assign coordinates ──
  const isLR = ast.direction === "lr";
  // primary axis = flow direction (down for tb, right for lr)
  // cross axis = within-rank spread
  const layerCenter: number[] = [];
  let primary = EPC_CONST.CANVAS_PAD + (ast.title ? EPC_CONST.TITLE_H : 0);
  for (let r = 0; r <= maxLayer; r++) {
    const bandThickness = Math.max(
      0,
      ...ranks[r]!.map((id) => (isLR ? sized.get(id)!.w : sized.get(id)!.h))
    );
    layerCenter[r] = primary + bandThickness / 2;
    primary += bandThickness + EPC_CONST.LAYER_GAP;
  }
  const primaryExtent = primary - EPC_CONST.LAYER_GAP + EPC_CONST.CANVAS_PAD;

  // Cross-axis: lay each rank out left-to-right, then center all ranks on a
  // common axis so the chain reads as a vertical spine.
  const crossPos = new Map<string, number>(); // center on cross axis
  let maxCrossExtent = 0;
  const rankWidths: number[] = [];
  for (let r = 0; r <= maxLayer; r++) {
    let cursor = 0;
    for (const id of ranks[r]!) {
      const s = sized.get(id)!;
      const span = isLR ? s.h : s.w;
      crossPos.set(id, cursor + span / 2);
      cursor += span + EPC_CONST.NODE_GAP;
    }
    const total = Math.max(0, cursor - EPC_CONST.NODE_GAP);
    rankWidths[r] = total;
    maxCrossExtent = Math.max(maxCrossExtent, total);
  }
  // Center each rank.
  for (let r = 0; r <= maxLayer; r++) {
    const shift = (maxCrossExtent - rankWidths[r]!) / 2 + EPC_CONST.CANVAS_PAD;
    for (const id of ranks[r]!) crossPos.set(id, crossPos.get(id)! + shift);
  }
  // The back-edge rail only needs reserved cross-axis space when loop-backs
  // actually exist. Reserving it unconditionally left a one-sided whitespace
  // band that pushed the (canvas-centered) title and content off to one side.
  const backMargin = backSet.size > 0 ? EPC_CONST.BACK_MARGIN : 0;
  const crossExtent = maxCrossExtent + EPC_CONST.CANVAS_PAD * 2 + backMargin;

  // Build layout nodes.
  const flaggedIds = new Set<string>();
  for (const v of analysis.violations) {
    if (v.severity === "error") for (const id of v.nodes) flaggedIds.add(id);
  }

  const layoutNodes: EpcLayoutNode[] = ast.nodes.map((n) => {
    const s = sized.get(n.id)!;
    const along = layerCenter[layer.get(n.id) ?? 0]!;
    const across = crossPos.get(n.id)!;
    const cx = isLR ? along : across;
    const cy = isLR ? across : along;
    return {
      node: n,
      cx,
      cy,
      width: s.w,
      height: s.h,
      layer: layer.get(n.id) ?? 0,
      flagged: flaggedIds.has(n.id),
    };
  });
  const nodePos = new Map(layoutNodes.map((ln) => [ln.node.id, ln] as const));

  // Build edges.
  const layoutEdges: EpcLayoutEdge[] = ast.edges.map((e) => {
    const back = backSet.has(`${e.from}�${e.to}`);
    return routeEdge(e, nodePos, crossExtent, back, isLR);
  });

  const width = isLR ? primaryExtent : crossExtent;
  const height = isLR ? crossExtent : primaryExtent;

  return {
    ast,
    analysis,
    nodes: layoutNodes,
    edges: layoutEdges,
    width: Math.max(width, EPC_CONST.CANVAS_PAD * 2 + 120),
    height: Math.max(height, EPC_CONST.CANVAS_PAD * 2 + 80),
  };

  void byId;
}

// ─── Sizing ───────────────────────────────────────────────────

function sizeOf(n: EpcNode): Sized {
  if (n.kind === "connector") {
    return { id: n.id, w: EPC_CONST.CONN_R * 2, h: EPC_CONST.CONN_R * 2 };
  }
  if (n.kind === "event") {
    return { id: n.id, w: EPC_CONST.EVENT_W, h: EPC_CONST.EVENT_H };
  }
  return { id: n.id, w: EPC_CONST.FUNC_W, h: EPC_CONST.FUNC_H };
}

// ─── Layering ─────────────────────────────────────────────────

/**
 * Longest-path layering: rank(n) = max over predecessors (rank(pred)+1), with
 * source nodes (no DAG predecessors) at rank 0. Deterministic topological order.
 */
function longestPathLayers(
  ast: EpcAst,
  dagOut: Map<string, string[]>,
  dagIn: Map<string, string[]>
): Map<string, number> {
  const layer = new Map<string, number>();
  const indeg = new Map<string, number>();
  for (const n of ast.nodes) indeg.set(n.id, (dagIn.get(n.id) ?? []).length);

  // Kahn topological order (declaration order tie-break).
  const queue: string[] = ast.nodes.filter((n) => (indeg.get(n.id) ?? 0) === 0).map((n) => n.id);
  for (const id of queue) layer.set(id, 0);

  const order: string[] = [];
  const localIndeg = new Map(indeg);
  let head = 0;
  while (head < queue.length) {
    const id = queue[head++]!;
    order.push(id);
    for (const s of dagOut.get(id) ?? []) {
      localIndeg.set(s, (localIndeg.get(s) ?? 0) - 1);
      if ((localIndeg.get(s) ?? 0) === 0) {
        queue.push(s);
      }
    }
  }
  // Any nodes left out (cycles fully consumed by back-edge removal shouldn't
  // happen, but guard): append in declaration order.
  for (const n of ast.nodes) if (!order.includes(n.id)) order.push(n.id);

  for (const id of order) {
    let best = 0;
    for (const p of dagIn.get(id) ?? []) best = Math.max(best, (layer.get(p) ?? 0) + 1);
    layer.set(id, best);
  }
  return layer;
}

// ─── Within-rank ordering ─────────────────────────────────────

function orderRanks(ranks: string[][], dagIn: Map<string, string[]>, ast: EpcAst): void {
  const declIndex = new Map(ast.nodes.map((n, i) => [n.id, i] as const));
  for (let r = 1; r < ranks.length; r++) {
    const prevIndex = new Map<string, number>();
    ranks[r - 1]!.forEach((id, i) => prevIndex.set(id, i));
    const bary = new Map<string, number>();
    for (const id of ranks[r]!) {
      const preds = (dagIn.get(id) ?? []).map((p) => prevIndex.get(p)).filter((v): v is number => v !== undefined);
      bary.set(id, preds.length ? preds.reduce((a, b) => a + b, 0) / preds.length : (declIndex.get(id) ?? 0));
    }
    ranks[r]!.sort((a, b) => {
      const d = (bary.get(a) ?? 0) - (bary.get(b) ?? 0);
      if (Math.abs(d) > 1e-9) return d;
      return (declIndex.get(a) ?? 0) - (declIndex.get(b) ?? 0);
    });
  }
}

// ─── Back-edge detection ──────────────────────────────────────

function detectBackEdges(ast: EpcAst, out: Map<string, string[]>): EpcEdge[] {
  const WHITE = 0, GREY = 1, BLACK = 2;
  const colour = new Map<string, number>(ast.nodes.map((n) => [n.id, WHITE] as const));
  const back: EpcEdge[] = [];
  const edgeByPair = new Map<string, EpcEdge>();
  for (const e of ast.edges) edgeByPair.set(`${e.from}�${e.to}`, e);

  const seeds = ast.nodes.filter((n) => (out.get(n.id) ?? []).length >= 0).map((n) => n.id);
  // Start DFS from nodes with no incoming first, then anything else.
  const inDeg = new Map<string, number>(ast.nodes.map((n) => [n.id, 0] as const));
  for (const e of ast.edges) inDeg.set(e.to, (inDeg.get(e.to) ?? 0) + 1);
  const roots = ast.nodes.filter((n) => (inDeg.get(n.id) ?? 0) === 0).map((n) => n.id);
  const visitOrder = [...roots, ...seeds.filter((s) => !roots.includes(s))];

  const dfs = (id: string): void => {
    colour.set(id, GREY);
    for (const s of out.get(id) ?? []) {
      const c = colour.get(s) ?? WHITE;
      if (c === GREY) {
        const e = edgeByPair.get(`${id}�${s}`);
        if (e) back.push(e);
      } else if (c === WHITE) {
        dfs(s);
      }
    }
    colour.set(id, BLACK);
  };
  for (const r of visitOrder) if ((colour.get(r) ?? WHITE) === WHITE) dfs(r);
  return back;
}

// ─── Edge routing ─────────────────────────────────────────────

function routeEdge(
  e: EpcEdge,
  nodePos: Map<string, EpcLayoutNode>,
  crossExtent: number,
  back: boolean,
  isLR: boolean
): EpcLayoutEdge {
  const a = nodePos.get(e.from);
  const b = nodePos.get(e.to);
  if (!a || !b) {
    return { edge: e, path: "", tip: { x: 0, y: 0 }, mid: { x: 0, y: 0 }, backEdge: back };
  }

  if (back) {
    // Route around the right margin: out the side, down/along, back in.
    const railX = crossExtent - EPC_CONST.BACK_MARGIN / 2;
    const start = borderPoint(a, b, isLR);
    const end = borderPoint(b, a, isLR);
    const path = isLR
      ? `M ${start.x} ${start.y} L ${start.x} ${railX} L ${end.x} ${railX} L ${end.x} ${end.y}`
      : `M ${start.x} ${start.y} L ${railX} ${start.y} L ${railX} ${end.y} L ${end.x} ${end.y}`;
    return {
      edge: e,
      path,
      tip: end,
      mid: { x: railX, y: (start.y + end.y) / 2 },
      backEdge: true,
    };
  }

  const start = borderPoint(a, b, isLR);
  const end = borderPoint(b, a, isLR);
  const path = `M ${start.x} ${start.y} L ${end.x} ${end.y}`;
  return {
    edge: e,
    path,
    tip: end,
    mid: { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 },
    backEdge: false,
  };
}

/** Border intersection point of node `from`'s box toward node `to`. */
function borderPoint(from: EpcLayoutNode, to: EpcLayoutNode, _isLR: boolean): { x: number; y: number } {
  const dx = to.cx - from.cx;
  const dy = to.cy - from.cy;
  if (from.node.kind === "connector") {
    const r = EPC_CONST.CONN_R;
    const len = Math.hypot(dx, dy) || 1;
    return { x: from.cx + (dx / len) * r, y: from.cy + (dy / len) * r };
  }
  const hw = from.width / 2;
  const hh = from.height / 2;
  if (dx === 0 && dy === 0) return { x: from.cx, y: from.cy };
  // Intersect ray with the rectangle border.
  const scaleX = dx !== 0 ? hw / Math.abs(dx) : Infinity;
  const scaleY = dy !== 0 ? hh / Math.abs(dy) : Infinity;
  const scale = Math.min(scaleX, scaleY);
  return { x: from.cx + dx * scale, y: from.cy + dy * scale };
}
