/**
 * FMEA analysis — the computational differentiator.
 * Per docs/reference/40-FMEA-STANDARD.md §"Engine computation".
 *
 * 1. Flatten the nested AST (item → mode → cause) to one worksheet row per
 *    (item, mode, cause) triple. The mode's *worst* effect severity governs
 *    every row of that mode (multiple effects → max severity, §Edge cases).
 * 2. RPN = S × O × D per row (1–1000).
 * 3. Action Priority (AIAG-VDA severity-primary banding) per row.
 * 4. Sort by the chosen key (`ap` default, or `rpn`): for `ap`, order
 *    High > Medium > Low then tie-break by S desc then RPN desc — *never* RPN
 *    alone, which would re-introduce the bug AP was designed to fix.
 * 5. Flag rows over the threshold.
 * 6. Recompute after-action RPN/AP from revised S/O/D + the before/after delta.
 *
 * Pure functions over the AST. Deterministic. No deps.
 */

import type {
  FmeaActionPriority,
  FmeaAnalysis,
  FmeaAst,
  FmeaRankKey,
  FmeaRow,
  FmeaThreshold,
} from "./types";

/** RPN = S × O × D. */
export function rpn(sev: number, occ: number, det: number): number {
  return sev * occ * det;
}

/**
 * AIAG-VDA Action Priority from (S, O, D).
 *
 * TODO(Victor): exact AIAG-VDA 2019 AP table — the published Handbook ships a
 * verbatim 1000-cell (S·O·D) decision table (and a separate FMEA-MSR S·F·M
 * table) that is paywalled and copyrighted. This implements the *band
 * structure* the standard doc captured (§"Engine computation" step 2):
 *
 *   - Severity is the primary axis, Occurrence second, Detection third.
 *   - S = 9–10 (safety/regulatory): High for EVERY O and D (even O=1,D=1) —
 *     the rule a pure-RPN sort gets wrong (airbag fails S10·O2·D3 → High).
 *   - S = 7–8: High at mid/high O; degrades Medium→Low as O falls; O=1 → Low.
 *   - S = 4–6: High only at very high O (8–10) with weak detection; else
 *     Medium/Low, trending Low as O drops.
 *   - S = 2–3: Medium or Low (Medium only at high O with weak D).
 *   - S = 1: Low for every O and D.
 *   - Within a non-extreme cell, worse detection (higher D) bumps the cell up.
 *
 * Replace this banded approximation with the verbatim table when transcribed;
 * keep the spot-check tests (S10·O1·D1=High, S1·O10·D10=Low, S7·O6·D7=High).
 */
export function actionPriority(sev: number, occ: number, det: number): FmeaActionPriority {
  // S = 9–10 → always High (severity dominates).
  if (sev >= 9) return "High";
  // S = 1 → always Low.
  if (sev <= 1) return "Low";

  // Detection bump: a high D (poor detection) escalates within a band.
  const weakDetection = det >= 7; // 7–10 = low/no detection
  const midDetection = det >= 4 && det <= 6;

  if (sev >= 7) {
    // S = 7–8.
    if (occ <= 1) return "Low";
    if (occ >= 6) return "High";
    if (occ >= 4) return weakDetection ? "High" : "Medium";
    // occ 2–3
    if (weakDetection) return "Medium";
    return midDetection ? "Medium" : "Low";
  }

  if (sev >= 4) {
    // S = 4–6.
    if (occ >= 8) return weakDetection ? "High" : "Medium";
    if (occ >= 6) return weakDetection ? "Medium" : "Medium";
    if (occ >= 4) return weakDetection ? "Medium" : "Low";
    if (occ >= 2) return weakDetection ? "Medium" : "Low";
    return "Low";
  }

  // S = 2–3.
  if (occ >= 6 && weakDetection) return "Medium";
  if (occ >= 8) return "Medium";
  return "Low";
}

/** Action obligation phrasing carried by each AP level (for <desc> / data-*). */
export function apObligation(ap: FmeaActionPriority): string {
  switch (ap) {
    case "High": return "action needed";
    case "Medium": return "action should be taken";
    case "Low": return "could improve";
  }
}

const AP_ORDER: Record<FmeaActionPriority, number> = { High: 3, Medium: 2, Low: 1 };

function meetsThreshold(t: FmeaThreshold, rpnVal: number, ap: FmeaActionPriority): boolean {
  if (t.key === "rpn") {
    const v = t.value as number;
    switch (t.op) {
      case ">": return rpnVal > v;
      case ">=": return rpnVal >= v;
      case "<": return rpnVal < v;
      case "<=": return rpnVal <= v;
      case "==": return rpnVal === v;
    }
  } else {
    const target = AP_ORDER[t.value as FmeaActionPriority];
    const got = AP_ORDER[ap];
    switch (t.op) {
      case ">": return got > target;
      case ">=": return got >= target;
      case "<": return got < target;
      case "<=": return got <= target;
      case "==": return got === target;
    }
  }
  return false;
}

interface FlatRow {
  item: string;
  fn?: string;
  mode: string;
  effect: string;
  effects: string[];
  sev: number;
  cause: string;
  occ: number;
  det: number;
  controls?: FmeaRow["controls"];
  action?: FmeaRow["action"];
  // grouping bookkeeping
  itemKey: string;
  modeKey: string;
}

export function analyseFmea(ast: FmeaAst): FmeaAnalysis {
  const notes: string[] = [];
  const flat: FlatRow[] = [];

  for (const it of ast.items) {
    const itemKey = it.item;
    for (const mode of it.modes) {
      const modeKey = `${itemKey}�${mode.text}`;
      // Worst effect governs the row (§Edge cases: max severity).
      const sev = mode.effects.length
        ? Math.max(...mode.effects.map((e) => e.sev))
        : 1;
      const governing = mode.effects.length
        ? mode.effects.reduce((a, b) => (b.sev > a.sev ? b : a))
        : { text: "", sev: 1 };
      const effects = mode.effects.map((e) => e.text);

      const causes = mode.causes.length
        ? mode.causes
        : // mode with no causes still produces one row (cause unknown)
          [{ text: "(cause not specified)", occ: 1, det: 10 }];

      for (const cause of causes) {
        // Detection-inversion authoring check: D=1 paired with no detection
        // control is suspicious (someone may have rated "1 = bad").
        if (cause.det === 1 && !cause.controls?.detection) {
          notes.push(
            `Possible Detection-inversion: "${mode.text}" cause "${cause.text}" rated det:1 with no detection control (D=1 means "almost certainly caught").`,
          );
        }
        flat.push({
          item: it.item,
          fn: it.fn,
          mode: mode.text,
          effect: governing.text,
          effects,
          sev,
          cause: cause.text,
          occ: cause.occ,
          det: cause.det,
          controls: cause.controls,
          itemKey,
          modeKey,
        });
      }
    }
  }

  // Attach after-action revisions.
  for (const act of ast.actions) {
    const target = flat.find(
      (r) => r.mode === act.mode && (act.cause === undefined || r.cause === act.cause),
    );
    if (!target) {
      notes.push(`Action references unknown mode/cause "${act.mode}"${act.cause ? ` / "${act.cause}"` : ""}.`);
      continue;
    }
    const rSev = act.revisedSev ?? target.sev;
    const rOcc = act.revisedOcc ?? target.occ;
    const rDet = act.revisedDet ?? target.det;
    const afterRpn = rpn(rSev, rOcc, rDet);
    target.action = {
      recommendation: act.recommendation,
      owner: act.owner,
      target: act.target,
      status: act.status,
      sev: rSev,
      occ: rOcc,
      det: rDet,
      rpn: afterRpn,
      ap: actionPriority(rSev, rOcc, rDet),
      rpnDelta: rpn(target.sev, target.occ, target.det) - afterRpn,
    };
  }

  // Compute RPN/AP, build rows.
  const rows: FmeaRow[] = flat.map((r) => {
    const r0 = rpn(r.sev, r.occ, r.det);
    const ap = actionPriority(r.sev, r.occ, r.det);
    const flagged = ast.flag ? meetsThreshold(ast.flag, r0, ap) : false;
    return {
      index: 0,
      item: r.item,
      fn: r.fn,
      mode: r.mode,
      effect: r.effect,
      effects: r.effects,
      sev: r.sev,
      cause: r.cause,
      occ: r.occ,
      det: r.det,
      controls: r.controls,
      rpn: r0,
      ap,
      flagged,
      action: r.action,
      itemFirst: false,
      itemSpan: 1,
      modeFirst: false,
      modeSpan: 1,
    };
  });

  // Sort by the chosen key. Keep a stable original index so equal-rank rows
  // preserve declaration order (deterministic).
  const orig = new Map(rows.map((r, i) => [r, i] as const));
  rows.sort((a, b) => compareRows(a, b, ast.rank, orig));

  // Re-number after sort.
  rows.forEach((r, i) => { r.index = i + 1; });

  // Compute item/mode vertical spans for left-cell merging (in sorted order).
  computeSpans(rows);

  const flaggedCount = rows.filter((r) => r.flagged).length;
  const maxRpn = rows.reduce((m, r) => Math.max(m, r.rpn), 0);
  const hasActions = rows.some((r) => r.action !== undefined);

  return { rank: ast.rank, rows, flaggedCount, maxRpn, hasActions, notes };
}

function compareRows(a: FmeaRow, b: FmeaRow, rank: FmeaRankKey, orig: Map<FmeaRow, number>): number {
  if (rank === "ap") {
    const d = AP_ORDER[b.ap] - AP_ORDER[a.ap];
    if (d !== 0) return d;
    if (b.sev !== a.sev) return b.sev - a.sev; // severity tie-break (never RPN alone)
    if (b.rpn !== a.rpn) return b.rpn - a.rpn;
  } else {
    if (b.rpn !== a.rpn) return b.rpn - a.rpn;
    if (b.sev !== a.sev) return b.sev - a.sev;
  }
  return (orig.get(a) ?? 0) - (orig.get(b) ?? 0);
}

/**
 * After sorting, adjacent rows that share the same item / mode get merged
 * left cells. We only merge runs that are *contiguous* in the sorted output
 * (sorting can scatter an item's modes by risk — merging non-adjacent rows
 * would be visually wrong).
 */
function computeSpans(rows: FmeaRow[]): void {
  let i = 0;
  while (i < rows.length) {
    let j = i;
    while (j + 1 < rows.length && rows[j + 1]!.item === rows[i]!.item) j++;
    const span = j - i + 1;
    rows[i]!.itemFirst = true;
    rows[i]!.itemSpan = span;
    for (let k = i + 1; k <= j; k++) { rows[k]!.itemFirst = false; rows[k]!.itemSpan = span; }
    i = j + 1;
  }
  i = 0;
  while (i < rows.length) {
    let j = i;
    while (
      j + 1 < rows.length &&
      rows[j + 1]!.item === rows[i]!.item &&
      rows[j + 1]!.mode === rows[i]!.mode
    ) j++;
    const span = j - i + 1;
    rows[i]!.modeFirst = true;
    rows[i]!.modeSpan = span;
    for (let k = i + 1; k <= j; k++) { rows[k]!.modeFirst = false; rows[k]!.modeSpan = span; }
    i = j + 1;
  }
}
