/**
 * Markov chain layout — deterministic, no randomness.
 *
 * Spec: docs/reference/42-MARKOV-CHAIN-STANDARD.md §"Visual conventions"
 *
 *   - States are placed on a ring (`layout: ring`, default) or in transient →
 *     absorbing tiers (`layout: layered`). Ring matches the canonical finance /
 *     weather reference figures and gives stable golden strings.
 *   - Opposite-direction pairs (i→j and j→i) are drawn as two curved arcs that
 *     **bow apart** — the single most important geometric requirement. A pair is
 *     detected and each side is offset perpendicular to the chord.
 *   - Self-loops curl outward from the node (radially away from the ring centre,
 *     or upward in layered mode), carrying the stay-probability pᵢᵢ.
 */

import { analyseMarkov } from "./analysis";
import type {
  MarkovArcGeom,
  MarkovAst,
  MarkovLayoutResult,
  MarkovPoint,
  MarkovStateBox,
} from "./types";

export const MARKOV_CONST = {
  STATE_R: 30,
  /** Min gap between adjacent state circles on the ring. */
  RING_GAP: 70,
  PADDING: 56,
  /** How far a bidirectional arc bows away from the straight chord. */
  BOW: 26,
  /** A lone (unpaired) arc still gets a slight bow so labels clear the line. */
  SOLO_BOW: 12,
  /** Self-loop radius and how far it protrudes past the circle. */
  LOOP_R: 18,
  LOOP_OUT: 30,
  /** Layered-mode tier spacing. */
  TIER_DX: 150,
  TIER_DY: 110,
  TITLE_BAND: 32,
} as const;

export function layoutMarkov(ast: MarkovAst): MarkovLayoutResult {
  const analysis = analyseMarkov(ast);
  const C = MARKOV_CONST;
  const states = ast.states;
  const n = states.length;

  const classOf = analysis.classification?.byState;
  const piMap = analysis.stationary?.unique ? analysis.stationary.pi : undefined;
  const perClassPi: Record<string, number> = {};
  if (analysis.stationary && !analysis.stationary.unique) {
    for (const c of analysis.stationary.perClass) Object.assign(perClassPi, c.pi);
  }

  // ── Place state centres ──
  const centres = new Map<string, MarkovPoint>();
  let width = 0;
  let height = 0;

  if (ast.layout === "layered" && analysis.classification) {
    ({ width, height } = placeLayered(ast, analysis.classification, centres, C));
  } else {
    ({ width, height } = placeRing(states.map((s) => s.id), centres, C));
  }

  const ringCenter: MarkovPoint = { x: width / 2, y: height / 2 };

  const boxes: MarkovStateBox[] = states.map((st) => {
    const c = centres.get(st.id)!;
    const tag = classOf?.[st.id];
    const isAbsorbing = tag === "absorbing";
    const pi = piMap?.[st.id] ?? perClassPi[st.id];
    const box: MarkovStateBox = {
      state: st,
      cx: c.x,
      cy: c.y,
      r: C.STATE_R,
      isAbsorbing,
    };
    if (tag) box.classTag = tag;
    if (pi !== undefined) box.pi = pi;
    return box;
  });

  // ── Arc geometry ──
  // Detect bidirectional pairs so each side bows the opposite way.
  const arcKey = (a: string, b: string): string => `${a}�${b}`;
  const present = new Set<string>();
  for (const tr of ast.transitions) present.add(arcKey(tr.from, tr.to));

  const arcs: MarkovArcGeom[] = ast.transitions.map((tr) => {
    if (tr.self) {
      return selfLoopGeom(tr, centres.get(tr.from)!, ringCenter, ast.layout, C);
    }
    const a = centres.get(tr.from)!;
    const b = centres.get(tr.to)!;
    const hasReverse = present.has(arcKey(tr.to, tr.from));
    // Deterministic side: the lexicographically-smaller endpoint bows +1.
    const sign = hasReverse ? (tr.from < tr.to ? 1 : -1) : 1;
    const bow = hasReverse ? C.BOW : C.SOLO_BOW;
    return curvedArcGeom(tr, a, b, sign * bow, C);
  });

  void n;
  return {
    width,
    height: height + (ast.title ? C.TITLE_BAND : 0),
    ...(ast.title ? { title: ast.title } : {}),
    states: boxes,
    arcs,
    analysis,
    ast,
  };
}

// ─── Placement ────────────────────────────────────────────────────

function placeRing(
  ids: string[],
  centres: Map<string, MarkovPoint>,
  C: typeof MARKOV_CONST,
): { width: number; height: number } {
  const n = ids.length;
  if (n === 1) {
    const cx = C.PADDING + C.STATE_R + C.LOOP_OUT;
    const cy = C.PADDING + C.STATE_R + C.LOOP_OUT;
    centres.set(ids[0]!, { x: cx, y: cy });
    const dim = 2 * (cx);
    return { width: dim, height: dim };
  }
  if (n === 2) {
    // Two states side by side (matches the canonical two-state weather figure).
    const cy = C.PADDING + C.STATE_R + C.LOOP_OUT;
    const dx = 2 * C.STATE_R + C.RING_GAP + 60;
    const cx0 = C.PADDING + C.STATE_R + C.LOOP_OUT;
    centres.set(ids[0]!, { x: cx0, y: cy });
    centres.set(ids[1]!, { x: cx0 + dx, y: cy });
    const width = cx0 + dx + C.STATE_R + C.LOOP_OUT + C.PADDING;
    const height = cy + C.STATE_R + C.LOOP_OUT + C.PADDING;
    return { width, height };
  }
  // Ring: choose a radius so neighbouring circles clear RING_GAP.
  const minArc = 2 * C.STATE_R + C.RING_GAP;
  const radius = Math.max(minArc / (2 * Math.sin(Math.PI / n)), 2 * C.STATE_R);
  const margin = C.PADDING + C.STATE_R + C.LOOP_OUT;
  const cx0 = margin + radius;
  const cy0 = margin + radius;
  ids.forEach((id, i) => {
    // Start at the top and go clockwise for a stable, readable order.
    const theta = -Math.PI / 2 + (2 * Math.PI * i) / n;
    centres.set(id, {
      x: cx0 + radius * Math.cos(theta),
      y: cy0 + radius * Math.sin(theta),
    });
  });
  const dim = 2 * (radius + margin);
  return { width: dim, height: dim };
}

function placeLayered(
  ast: MarkovAst,
  classification: NonNullable<MarkovLayoutResult["analysis"]["classification"]>,
  centres: Map<string, MarkovPoint>,
  C: typeof MARKOV_CONST,
): { width: number; height: number } {
  // Tier 0: transient; Tier 1: recurrent (non-absorbing); Tier 2: absorbing.
  const tier = (id: string): number => {
    const k = classification.byState[id];
    if (k === "absorbing") return 2;
    if (k === "recurrent") return 1;
    return 0;
  };
  const cols: string[][] = [[], [], []];
  for (const st of ast.states) cols[tier(st.id)]!.push(st.id);

  const maxRows = Math.max(1, ...cols.map((c) => c.length));
  const margin = C.PADDING + C.STATE_R + C.LOOP_OUT;
  cols.forEach((col, ci) => {
    const x = margin + ci * C.TIER_DX;
    const totalH = (col.length - 1) * C.TIER_DY;
    const startY = margin + ((maxRows - 1) * C.TIER_DY - totalH) / 2;
    col.forEach((id, ri) => centres.set(id, { x, y: startY + ri * C.TIER_DY }));
  });

  const width = margin + 2 * C.TIER_DX + C.STATE_R + C.LOOP_OUT + C.PADDING;
  const height = margin + (maxRows - 1) * C.TIER_DY + C.STATE_R + C.LOOP_OUT + C.PADDING;
  return { width, height };
}

// ─── Arc shapes ───────────────────────────────────────────────────

/** A curved (quadratic-style, expressed as cubic) arc from circle a to circle b,
 * bowing `bow` units perpendicular to the chord midpoint. */
function curvedArcGeom(
  tr: MarkovArcGeom["transition"],
  a: MarkovPoint,
  b: MarkovPoint,
  bow: number,
  C: typeof MARKOV_CONST,
): MarkovArcGeom {
  // Normal is computed from a *canonical* orientation (from→to) so that the
  // caller's signed `bow` lands on a stable world-space side. For a bidirectional
  // pair the two arcs pass opposite signs, so they bow to opposite sides even
  // though each traverses the chord in the reverse direction.
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  // Unit normal (perpendicular), flipped to a canonical world orientation so the
  // sign is independent of which endpoint is `from`.
  const flip = a.x < b.x || (a.x === b.x && a.y <= b.y) ? 1 : -1;
  const nx = -uy * flip;
  const ny = ux * flip;

  const mid: MarkovPoint = {
    x: (a.x + b.x) / 2 + nx * bow,
    y: (a.y + b.y) / 2 + ny * bow,
  };

  // Re-aim the endpoints at the bowed midpoint so the arc leaves/enters cleanly.
  const start = aimToBoundary(a, mid, C.STATE_R);
  const end = aimToBoundary(b, mid, C.STATE_R);

  // Cubic control points: pull both toward the bowed midpoint.
  const c1: MarkovPoint = { x: (start.x + mid.x) / 2, y: (start.y + mid.y) / 2 };
  const c2: MarkovPoint = { x: (end.x + mid.x) / 2, y: (end.y + mid.y) / 2 };

  return {
    transition: tr,
    points: [start, c1, c2, end],
    self: false,
    labelX: mid.x,
    labelY: mid.y,
  };
}

/** Point on the boundary of the circle at `centre`, aimed toward `target`. */
function aimToBoundary(centre: MarkovPoint, target: MarkovPoint, r: number): MarkovPoint {
  const dx = target.x - centre.x;
  const dy = target.y - centre.y;
  const len = Math.hypot(dx, dy) || 1;
  return { x: centre.x + (dx / len) * r, y: centre.y + (dy / len) * r };
}

/** Self-loop curling outward from the node (away from the ring centre, or up in
 * layered mode). Represented as a 4-point cubic loop. */
function selfLoopGeom(
  tr: MarkovArcGeom["transition"],
  c: MarkovPoint,
  ringCenter: MarkovPoint,
  layout: MarkovAst["layout"],
  C: typeof MARKOV_CONST,
): MarkovArcGeom {
  // Outward radial direction (fallback: straight up).
  let ox = c.x - ringCenter.x;
  let oy = c.y - ringCenter.y;
  if (layout === "layered" || (ox === 0 && oy === 0)) {
    ox = 0;
    oy = -1;
  }
  const ol = Math.hypot(ox, oy) || 1;
  const ux = ox / ol;
  const uy = oy / ol;
  // Tangent (perpendicular) to spread the two loop feet apart.
  const tx = -uy;
  const ty = ux;

  const spread = C.STATE_R * 0.6;
  const foot1: MarkovPoint = {
    x: c.x + ux * C.STATE_R * 0.85 - tx * spread,
    y: c.y + uy * C.STATE_R * 0.85 - ty * spread,
  };
  const foot2: MarkovPoint = {
    x: c.x + ux * C.STATE_R * 0.85 + tx * spread,
    y: c.y + uy * C.STATE_R * 0.85 + ty * spread,
  };
  const apex: MarkovPoint = {
    x: c.x + ux * (C.STATE_R + C.LOOP_OUT),
    y: c.y + uy * (C.STATE_R + C.LOOP_OUT),
  };
  const ctrl1: MarkovPoint = {
    x: foot1.x + ux * C.LOOP_OUT - tx * C.LOOP_R,
    y: foot1.y + uy * C.LOOP_OUT - ty * C.LOOP_R,
  };
  const ctrl2: MarkovPoint = {
    x: foot2.x + ux * C.LOOP_OUT + tx * C.LOOP_R,
    y: foot2.y + uy * C.LOOP_OUT + ty * C.LOOP_R,
  };

  return {
    transition: tr,
    // [foot1, ctrl1, ctrl2, foot2] — a wide loop; apex used for the label.
    points: [foot1, ctrl1, ctrl2, foot2],
    self: true,
    labelX: apex.x + ux * 8,
    labelY: apex.y + uy * 8,
  };
}
