import type {
  MatrixAST,
  MatrixPoint,
  MatrixCell,
  MatrixConfig,
  MatrixAxis,
  LabelCollisionMode,
  MatrixTemplate,
  SipocData,
  QfdData,
  QfdStrength,
  QfdCorrelation,
  PunnettGene,
} from "./types";
import { resolveTemplate, applyTemplateDefaults } from "./templates";

const TEMPLATE_NAMES: ReadonlySet<string> = new Set([
  "eisenhower",
  "impact-effort",
  "rice",
  "bcg",
  "ansoff",
  "johari",
  "9-box",
  "risk-matrix",
]);

const DEFAULT_CONFIG: MatrixConfig = {
  quadrantBg: true,
  gridLines: true,
  axisArrows: true,
  labelCollision: "auto",
  bubbleScale: "area",
  quadrantAnnotations: true,
  legendPosition: "bottom-right",
  offChartPolicy: "clamp-badge",
  showAxis: "auto",
  margins: false,
};

interface PunnettScratch {
  p1raw?: string;
  p2raw?: string;
  traits: Record<string, { dominant: string; recessive?: string }>;
}

interface ParseState {
  ast: MatrixAST;
  pointIdSeq: number;
  punnett?: PunnettScratch;
}

function emptyAxis(): MatrixAxis {
  return { low: "", high: "" };
}

function emptySipoc(): SipocData {
  return { suppliers: [], inputs: [], process: [], outputs: [], customers: [] };
}

function emptyQfd(): QfdData {
  return { whats: [], hows: [], relationships: [], roof: [], normalize: false };
}

/** Split a quoted, comma-separated item list: `"A", "B", "C"` → ["A","B","C"]. */
function parseItemList(raw: string): string[] {
  return parseNumberList(raw);
}

/** Map a raw token to a QFD relationship strength (9/3/1), or undefined. */
function parseStrength(tok: string): QfdStrength | undefined {
  const t = tok.trim().toLowerCase();
  if (t === "9" || t === "strong" || t === "●" || t === "◉" || t === "⬤") return 9;
  if (t === "3" || t === "medium" || t === "○" || t === "◯" || t === "o") return 3;
  if (t === "1" || t === "weak" || t === "△" || t === "▽" || t === "▲") return 1;
  return undefined;
}

/** Map a raw token to a QFD roof correlation, or undefined. */
function parseCorrelation(tok: string): QfdCorrelation | undefined {
  const t = tok.trim();
  if (t === "++" || /^strong\+?$/i.test(t) || t === "◎") return "++";
  if (t === "+" || /^pos(itive)?$/i.test(t) || t === "○") return "+";
  if (t === "--" || t === "−−" || /^strong-$/i.test(t) || t === "✕" || t === "✖" || t === "×") return "--";
  if (t === "-" || t === "−" || /^neg(ative)?$/i.test(t) || t === "✗") return "-";
  return undefined;
}

function quadrantToCell(q: 1 | 2 | 3 | 4): { col: number; row: number } {
  // 2×2 mapping: Q1=top-right, Q2=top-left, Q3=bottom-left, Q4=bottom-right
  // (rows: 0=bottom, 1=top)
  switch (q) {
    case 1: return { col: 1, row: 1 };
    case 2: return { col: 0, row: 1 };
    case 3: return { col: 0, row: 0 };
    case 4: return { col: 1, row: 0 };
  }
}

function newAST(): MatrixAST {
  return {
    type: "matrix",
    mode: "quadrant",
    grid: "2x2",
    cols: 2,
    rows: 2,
    xAxis: emptyAxis(),
    yAxis: emptyAxis(),
    points: [],
    cells: [],
    cellLabels: [],
    annotations: [],
    config: { ...DEFAULT_CONFIG },
  };
}

function stripQuotes(s: string): string {
  const t = s.trim();
  if ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'"))) {
    return t.slice(1, -1);
  }
  return t;
}

function readQuoted(line: string, from: number): { text: string; next: number } | null {
  // skip whitespace
  let i = from;
  while (i < line.length && /\s/.test(line[i]!)) i++;
  if (line[i] !== '"' && line[i] !== "'") return null;
  const quote = line[i]!;
  const start = i + 1;
  let end = start;
  while (end < line.length && line[end] !== quote) end++;
  if (end >= line.length) return null;
  return { text: line.slice(start, end), next: end + 1 };
}

function parseAxis(raw: string): MatrixAxis {
  // "Low Effort → High Effort" or "High Market Share ← Low Market Share"
  // or "Low → High" or "Low ↑ High" etc.
  const arrowMatch = raw.match(/\s*(→|↑|->|>|↓|←|<-|<)\s*/);
  if (arrowMatch) {
    const arrow = arrowMatch[1]!;
    const idx = arrowMatch.index!;
    const left = raw.slice(0, idx).trim();
    const right = raw.slice(idx + arrowMatch[0].length).trim();
    const reversed = arrow === "←" || arrow === "<-" || arrow === "<";
    if (reversed) {
      return { low: right, high: left, reversed: true };
    }
    return { low: left, high: right };
  }
  // Plain text: treat as high label, low stays empty
  return { low: "", high: raw.trim() };
}

function parseNumberList(raw: string): string[] {
  // "[A, B, C]" → ["A","B","C"]
  const t = raw.trim();
  const inner = t.startsWith("[") && t.endsWith("]") ? t.slice(1, -1) : t;
  return inner
    .split(",")
    .map((s) => stripQuotes(s.trim()))
    .filter((s) => s.length > 0);
}

function parseProperties(
  raw: string,
  point: MatrixPoint
): void {
  // e.g.  size: 5 category: design  note: "foo"  highlight: true
  let i = 0;
  while (i < raw.length) {
    // skip whitespace
    while (i < raw.length && /\s/.test(raw[i]!)) i++;
    if (i >= raw.length) break;
    // read key
    const keyMatch = raw.slice(i).match(/^([a-zA-Z_-]+)\s*:\s*/);
    if (!keyMatch) break;
    const key = keyMatch[1]!.toLowerCase();
    i += keyMatch[0].length;
    // read value: quoted, number, true/false, or bareword
    if (raw[i] === '"' || raw[i] === "'") {
      const q = readQuoted(raw, i);
      if (!q) break;
      if (key === "note") point.note = q.text;
      else if (key === "label") point.label = q.text;
      i = q.next;
    } else {
      // bareword until whitespace + next "key:"
      const rest = raw.slice(i);
      const endMatch = rest.match(/\s+[a-zA-Z_-]+\s*:/);
      const end = endMatch ? endMatch.index! : rest.length;
      const val = rest.slice(0, end).trim();
      i += end;
      if (key === "size") {
        const n = Number(val);
        if (!Number.isNaN(n)) point.size = n;
      } else if (key === "category") {
        point.category = val;
      } else if (key === "color") {
        point.color = val;
      } else if (key === "shape") {
        if (val === "circle" || val === "square" || val === "triangle" || val === "diamond") {
          point.shape = val;
        }
      } else if (key === "highlight") {
        point.highlight = val === "true" || val === "1";
      }
    }
  }
}

function parsePointLine(line: string, st: ParseState): boolean {
  // `"Label" at (x, y) size: 3 category: infra`
  const q = readQuoted(line, 0);
  if (!q) return false;
  const rest = line.slice(q.next).trim();
  const atMatch = rest.match(/^at\s*\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)\s*(.*)$/);
  if (!atMatch) return false;
  const x = Number(atMatch[1]);
  const y = Number(atMatch[2]);
  const props = atMatch[3]!;
  const offChart = x < 0 || x > 1 || y < 0 || y > 1;
  const clampedX = Math.max(0, Math.min(1, x));
  const clampedY = Math.max(0, Math.min(1, y));
  const point: MatrixPoint = {
    id: `p${st.pointIdSeq++}`,
    label: q.text,
    x: clampedX,
    y: clampedY,
    offChart,
    origX: offChart ? x : undefined,
    origY: offChart ? y : undefined,
  };
  if (props) parseProperties(props, point);
  st.ast.points.push(point);
  return true;
}

function parseCellLine(line: string, st: ParseState): boolean {
  // `cell (i,j) value: 9 label: "foo"`
  const m = line.match(/^cell\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)\s*(.*)$/i);
  if (!m) return false;
  const col = Number(m[1]);
  const row = Number(m[2]);
  const rest = m[3]!;
  const cell: MatrixCell = { col, row };
  const valMatch = rest.match(/value:\s*(-?\d+(?:\.\d+)?)/i);
  if (valMatch) cell.value = Number(valMatch[1]);
  const labMatch = rest.match(/label:\s*"([^"]*)"/i);
  if (labMatch) cell.label = labMatch[1]!;
  const lvlMatch = rest.match(/level:\s*(strong|medium|weak)\b/i);
  if (lvlMatch) {
    const lv = lvlMatch[1]!.toLowerCase() as "strong" | "medium" | "weak";
    cell.level = lv;
    if (cell.value === undefined) cell.value = lv === "strong" ? 3 : lv === "medium" ? 2 : 1;
  }
  st.ast.cells.push(cell);
  if (cell.label) {
    st.ast.cellLabels.push({ col, row, label: cell.label });
  }
  return true;
}

const SIPOC_KEYS: ReadonlyArray<keyof SipocData> = [
  "suppliers",
  "inputs",
  "process",
  "outputs",
  "customers",
];

/**
 * SIPOC section line: `suppliers: "A", "B"` (or `supplier:` singular).
 * Repeated lines for the same column append. Returns true if consumed.
 */
function parseSipocLine(line: string, ast: MatrixAST): boolean {
  if (!ast.sipoc) return false;
  const m = line.match(/^([a-zA-Z]+)\s*:\s*(.*)$/);
  if (!m) return false;
  let key = m[1]!.toLowerCase();
  // accept singular forms
  if (key === "supplier") key = "suppliers";
  else if (key === "input") key = "inputs";
  else if (key === "output") key = "outputs";
  else if (key === "customer") key = "customers";
  const col = SIPOC_KEYS.find((k) => k === key);
  if (!col) return false;
  const items = parseItemList(m[2]!);
  ast.sipoc[col].push(...items);
  return true;
}

/**
 * QFD line forms:
 *   what: "Quiet operation" weight: 5
 *   how: "Fan RPM" dir: down
 *   rel (what, how): 9       (or `cell (how, what) value: 9`)
 *   roof (i, j): ++
 *   normalize: true
 * Returns true if consumed.
 */
function parseQfdLine(line: string, ast: MatrixAST): boolean {
  const qfd = ast.qfd;
  if (!qfd) return false;

  // normalize toggle
  const normMatch = line.match(/^normali[sz]e\s*:\s*(.+)$/i);
  if (normMatch) {
    const v = normMatch[1]!.trim().toLowerCase();
    qfd.normalize = v === "true" || v === "on" || v === "1" || v === "percent" || v === "%";
    return true;
  }

  // what: "label" weight: N   (weight optional → defaults to 1)
  const whatMatch = line.match(/^what\s*:\s*(.*)$/i);
  if (whatMatch) {
    const q = readQuoted(whatMatch[1]!, 0);
    if (!q) return true;
    const rest = whatMatch[1]!.slice(q.next);
    const wMatch = rest.match(/(?:weight|wt|imp(?:ortance)?)\s*:\s*(-?\d+(?:\.\d+)?)/i);
    const weight = wMatch ? Number(wMatch[1]) : 1;
    qfd.whats.push({ label: q.text, weight });
    return true;
  }

  // how: "label" dir: up|down|target
  const howMatch = line.match(/^how\s*:\s*(.*)$/i);
  if (howMatch) {
    const q = readQuoted(howMatch[1]!, 0);
    if (!q) return true;
    const rest = howMatch[1]!.slice(q.next);
    const dMatch = rest.match(/(?:dir(?:ection)?|target)\s*:\s*([a-zA-Z↑↓○]+)/i);
    let direction: "up" | "down" | "target" | undefined;
    if (dMatch) {
      const d = dMatch[1]!.toLowerCase();
      if (d === "up" || d === "max" || d === "maximise" || d === "maximize" || d === "↑") direction = "up";
      else if (d === "down" || d === "min" || d === "minimise" || d === "minimize" || d === "↓") direction = "down";
      else if (d === "target" || d === "nominal" || d === "○") direction = "target";
    }
    qfd.hows.push(direction ? { label: q.text, direction } : { label: q.text });
    return true;
  }

  // rel (what, how): strength   — primary relationship form
  const relMatch = line.match(/^rel\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)\s*:?\s*(.+)$/i);
  if (relMatch) {
    const what = Number(relMatch[1]);
    const how = Number(relMatch[2]);
    const strength = parseStrength(relMatch[3]!);
    if (strength !== undefined) qfd.relationships.push({ what, how, strength });
    return true;
  }

  // cell (how, col=how, row=what) compatibility: `cell (how, what) value: 9`
  const cellMatch = line.match(/^cell\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)\s*(.*)$/i);
  if (cellMatch) {
    const how = Number(cellMatch[1]);
    const what = Number(cellMatch[2]);
    const valMatch = cellMatch[3]!.match(/value\s*:\s*(\d+)/i);
    const strength = valMatch ? parseStrength(valMatch[1]!) : undefined;
    if (strength !== undefined) qfd.relationships.push({ what, how, strength });
    return true;
  }

  // roof (i, j): correlation
  const roofMatch = line.match(/^roof\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)\s*:?\s*(.+)$/i);
  if (roofMatch) {
    let a = Number(roofMatch[1]);
    let b = Number(roofMatch[2]);
    if (a > b) [a, b] = [b, a];
    const correlation = parseCorrelation(roofMatch[3]!);
    if (correlation !== undefined && a !== b) qfd.roof.push({ a, b, correlation });
    return true;
  }

  return false;
}

/**
 * Parse a genotype token like "RrYy" into per-locus allele pairs.
 * Alleles of one locus share a letter (case-insensitive); case = dominance.
 * Returns null if malformed (odd length, mismatched letters, non-alpha).
 */
function parseGenotype(token: string): { letter: string; alleles: [string, string] }[] | null {
  const t = token.trim();
  if (t.length === 0 || t.length % 2 !== 0) return null;
  const loci: { letter: string; alleles: [string, string] }[] = [];
  for (let i = 0; i < t.length; i += 2) {
    const a = t[i]!;
    const b = t[i + 1]!;
    if (!/[A-Za-z]/.test(a) || !/[A-Za-z]/.test(b)) return null;
    if (a.toUpperCase() !== b.toUpperCase()) return null;
    loci.push({ letter: a.toUpperCase(), alleles: [a, b] });
  }
  return loci;
}

/**
 * Punnett line forms (mode `punnett`):
 *   cross: Bb x Bb            (also `parents:`; separator x / × / *)
 *   trait B: "Brown" / "Blue" (optional phenotype names: dominant / recessive)
 * Returns true if consumed.
 */
function parsePunnettLine(line: string, st: ParseState): boolean {
  if (!st.punnett) return false;
  const crossMatch = line.match(/^(?:cross|parents?)\s*:\s*(.+)$/i);
  if (crossMatch) {
    const parts = crossMatch[1]!.split(/\s*[x×*]\s*/i);
    if (parts.length === 2) {
      st.punnett.p1raw = parts[0]!.trim();
      st.punnett.p2raw = parts[1]!.trim();
    }
    return true;
  }
  const traitMatch = line.match(/^trait\s+([A-Za-z])\s*:\s*(.+)$/i);
  if (traitMatch) {
    const letter = traitMatch[1]!.toUpperCase();
    const slash = traitMatch[2]!.split("/");
    const dominant = stripQuotes(slash[0] ?? "");
    const recessive = slash[1] !== undefined ? stripQuotes(slash[1]) : undefined;
    st.punnett.traits[letter] = { dominant, recessive };
    return true;
  }
  return false;
}

function parseConfigLine(key: string, value: string, ast: MatrixAST): void {
  const k = key.trim().toLowerCase();
  const v = value.trim();
  if (k === "quadrantbg") ast.config.quadrantBg = v === "true";
  else if (k === "gridlines") ast.config.gridLines = v === "true";
  else if (k === "axisarrows") ast.config.axisArrows = v === "true";
  else if (k === "labelcollision") ast.config.labelCollision = v.replace(/"/g, "") as LabelCollisionMode;
  else if (k === "bubblescale") ast.config.bubbleScale = v === "radius" ? "radius" : "area";
  else if (k === "quadrantannotations") ast.config.quadrantAnnotations = v === "true";
  else if (k === "legendposition") {
    const t = v.replace(/"/g, "") as MatrixConfig["legendPosition"];
    ast.config.legendPosition = t;
  } else if (k === "offchartpolicy") {
    const t = v.replace(/"/g, "") as MatrixConfig["offChartPolicy"];
    ast.config.offChartPolicy = t;
  }
}

function parseHeader(line: string, ast: MatrixAST): MatrixTemplate | undefined {
  // `matrix eisenhower "Week"` / `matrix "Title"` / `matrix heatmap 5x5`
  const t = line.trim();
  const rest = t.slice("matrix".length).trim();
  // heatmap NxM
  const heatMatch = rest.match(/^heatmap\s+(\d+)\s*x\s*(\d+)\s*(.*)$/i);
  if (heatMatch) {
    ast.mode = "heatmap";
    ast.grid = "NxM";
    ast.cols = Number(heatMatch[1]);
    ast.rows = Number(heatMatch[2]);
    const title = heatMatch[3]!.trim();
    if (title) ast.title = stripQuotes(title);
    return undefined;
  }
  // correlation [NxM] "title"   — rows/cols come from rows:/cols: directive if not here
  const corrMatch = rest.match(/^correlation\s*(?:(\d+)\s*x\s*(\d+))?\s*(.*)$/i);
  if (corrMatch) {
    ast.mode = "correlation";
    ast.grid = "NxM";
    if (corrMatch[1] && corrMatch[2]) {
      ast.cols = Number(corrMatch[1]);
      ast.rows = Number(corrMatch[2]);
    }
    const title = corrMatch[3]!.trim();
    if (title) ast.title = stripQuotes(title);
    return undefined;
  }
  // sipoc "title"  — fixed 5-column Six Sigma scoping table
  const sipocMatch = rest.match(/^sipoc\b\s*(.*)$/i);
  if (sipocMatch) {
    ast.mode = "sipoc";
    ast.grid = "NxM";
    ast.cols = 5;
    ast.rows = 0;
    ast.sipoc = emptySipoc();
    const title = sipocMatch[1]!.trim();
    if (title) ast.title = stripQuotes(title);
    return undefined;
  }
  // qfd "title"  — QFD House of Quality relationship matrix
  const qfdMatch = rest.match(/^qfd\b\s*(.*)$/i);
  if (qfdMatch) {
    ast.mode = "qfd";
    ast.grid = "NxM";
    ast.qfd = emptyQfd();
    const title = qfdMatch[1]!.trim();
    if (title) ast.title = stripQuotes(title);
    return undefined;
  }
  // punnett "title"  — Mendelian Punnett-square cross
  const punnettMatch = rest.match(/^punnett\b\s*(.*)$/i);
  if (punnettMatch) {
    ast.mode = "punnett";
    ast.grid = "NxM";
    ast.punnett = { genes: [], parent1: [], parent2: [] };
    const title = punnettMatch[1]!.trim();
    if (title) ast.title = stripQuotes(title);
    return undefined;
  }

  // template name + optional title
  const tokenMatch = rest.match(/^([a-zA-Z0-9_-]+)\s*(.*)$/);
  if (tokenMatch) {
    const tok = tokenMatch[1]!.toLowerCase();
    const remainder = tokenMatch[2]!.trim();
    if (TEMPLATE_NAMES.has(tok)) {
      if (remainder) ast.title = stripQuotes(remainder);
      return tok as MatrixTemplate;
    }
    // treat as quoted title
    if (rest.startsWith('"') || rest.startsWith("'")) {
      ast.title = stripQuotes(rest);
    } else if (rest.length > 0) {
      ast.title = stripQuotes(rest);
    }
  }
  return undefined;
}

export function parseMatrix(text: string): MatrixAST {
  const st: ParseState = { ast: newAST(), pointIdSeq: 0 };
  const lines = text.split(/\r?\n/);
  let templateName: MatrixTemplate | undefined;
  let inConfig = false;

  for (const raw of lines) {
    // strip trailing comments (but keep # inside quotes)
    let line = raw;
    const hashIdx = findCommentStart(line);
    if (hashIdx >= 0) line = line.slice(0, hashIdx);
    line = line.trim();
    if (!line) {
      inConfig = false;
      continue;
    }

    if (/^matrix\b/i.test(line)) {
      templateName = parseHeader(line, st.ast);
      if (st.ast.mode === "punnett" && !st.punnett) st.punnett = { traits: {} };
      continue;
    }

    if (/^config\s*:/i.test(line)) {
      inConfig = true;
      continue;
    }

    // config key: value (indented under `config:`)
    if (inConfig) {
      const kv = line.match(/^([a-zA-Z]+)\s*:\s*(.+)$/);
      if (kv) {
        parseConfigLine(kv[1]!, kv[2]!, st.ast);
        continue;
      }
      inConfig = false;
    }

    if (/^title\s*:/i.test(line)) {
      st.ast.title = stripQuotes(line.replace(/^title\s*:\s*/i, ""));
      continue;
    }

    if (st.ast.mode === "sipoc" && parseSipocLine(line, st.ast)) continue;
    if (st.ast.mode === "qfd" && parseQfdLine(line, st.ast)) continue;
    if (st.ast.mode === "punnett" && parsePunnettLine(line, st)) continue;

    if (/^x-axis\s*:/i.test(line)) {
      st.ast.xAxis = parseAxis(line.replace(/^x-axis\s*:\s*/i, ""));
      continue;
    }
    if (/^y-axis\s*:/i.test(line)) {
      st.ast.yAxis = parseAxis(line.replace(/^y-axis\s*:\s*/i, ""));
      continue;
    }
    if (/^rows\s*:/i.test(line)) {
      st.ast.rowLabels = parseNumberList(line.replace(/^rows\s*:\s*/i, ""));
      if (st.ast.mode !== "quadrant") st.ast.rows = st.ast.rowLabels.length;
      continue;
    }
    if (/^cols\s*:/i.test(line)) {
      st.ast.colLabels = parseNumberList(line.replace(/^cols\s*:\s*/i, ""));
      if (st.ast.mode !== "quadrant") st.ast.cols = st.ast.colLabels.length;
      continue;
    }
    if (/^grid\s*:/i.test(line)) {
      const v = line.replace(/^grid\s*:\s*/i, "").trim().toLowerCase();
      const gm = v.match(/^(\d+)\s*x\s*(\d+)$/);
      if (gm) {
        const c = Number(gm[1]);
        const r = Number(gm[2]);
        st.ast.cols = c;
        st.ast.rows = r;
        if (c === 2 && r === 2) st.ast.grid = "2x2";
        else if (c === 3 && r === 3) st.ast.grid = "3x3";
        else st.ast.grid = "NxM";
      }
      continue;
    }
    if (/^quadrant\s+/i.test(line)) {
      // `quadrant Q1 "Do First" description: "..."`
      const m = line.match(/^quadrant\s+(?:Q)?(\d)\s*"([^"]*)"(.*)$/i);
      if (m) {
        const q = Number(m[1]) as 1 | 2 | 3 | 4;
        const rest = m[3]!.trim();
        const descMatch = rest.match(/description:\s*"([^"]*)"/i);
        const description = descMatch ? descMatch[1]! : undefined;
        if (q >= 1 && q <= 4) {
          const existing = st.ast.annotations.find((a) => a.q === q);
          if (existing) {
            existing.label = m[2]!;
            if (description) existing.description = description;
          } else {
            st.ast.annotations.push({ q, label: m[2]!, description });
          }
        }
      }
      continue;
    }

    if (/^axis\s*:/i.test(line)) {
      const v = line.replace(/^axis\s*:\s*/i, "").trim().toLowerCase().replace(/"/g, "");
      if (v === "none" || v === "off" || v === "hidden") st.ast.config.showAxis = "off";
      else if (v === "on" || v === "show" || v === "visible") st.ast.config.showAxis = "on";
      else st.ast.config.showAxis = "auto";
      continue;
    }

    if (/^margins\s*:/i.test(line)) {
      const v = line.replace(/^margins\s*:\s*/i, "").trim().toLowerCase();
      st.ast.config.margins = v === "true" || v === "on" || v === "1";
      continue;
    }

    if (/^style\s*:/i.test(line)) {
      const v = line.replace(/^style\s*:\s*/i, "").trim().toLowerCase().replace(/"/g, "");
      if (v === "table") {
        st.ast.config.showAxis = "off";
        st.ast.config.axisArrows = false;
        st.ast.config.gridLines = false;
        st.ast.config.quadrantAnnotations = false;
        st.ast.style = "table";
      }
      continue;
    }

    if (/^cell\s*\(/i.test(line)) {
      parseCellLine(line, st);
      continue;
    }

    // `Q1: "label"` shorthand for 2×2 cellLabel (Q1=TR, Q2=TL, Q3=BL, Q4=BR)
    const qShort = line.match(/^q([1-4])\s*:\s*(.+)$/i);
    if (qShort) {
      const q = Number(qShort[1]) as 1 | 2 | 3 | 4;
      const labelRaw = qShort[2]!.trim();
      const label = stripQuotes(labelRaw);
      const cell = quadrantToCell(q);
      st.ast.cellLabels.push({ col: cell.col, row: cell.row, label });
      continue;
    }

    // point line (starts with a quote)
    if (line.startsWith('"') || line.startsWith("'")) {
      if (parsePointLine(line, st)) continue;
    }
  }

  // Apply template defaults last (so explicit x-axis/y-axis override template)
  if (templateName) {
    const spec = resolveTemplate(templateName);
    if (spec) {
      applyTemplateDefaults(st.ast, spec);
      st.ast.template = templateName;
    }
  }

  // Promote 3x3 / NxM where cols/rows already say so but grid wasn't set
  if (
    st.ast.cols === 3 &&
    st.ast.rows === 3 &&
    st.ast.grid !== "NxM" &&
    st.ast.mode !== "sipoc" &&
    st.ast.mode !== "qfd"
  ) {
    st.ast.grid = "3x3";
  }
  if (
    st.ast.mode === "heatmap" ||
    st.ast.mode === "correlation" ||
    st.ast.mode === "sipoc" ||
    st.ast.mode === "qfd" ||
    st.ast.mode === "punnett"
  ) {
    st.ast.grid = "NxM";
  }

  // SIPOC: 5 fixed columns; rows = the longest column's item count.
  if (st.ast.mode === "sipoc" && st.ast.sipoc) {
    const s = st.ast.sipoc;
    st.ast.cols = 5;
    st.ast.rows = Math.max(
      s.suppliers.length,
      s.inputs.length,
      s.process.length,
      s.outputs.length,
      s.customers.length,
    );
  }

  // QFD: cols = HOWs, rows = WHATs.
  if (st.ast.mode === "qfd" && st.ast.qfd) {
    st.ast.cols = st.ast.qfd.hows.length;
    st.ast.rows = st.ast.qfd.whats.length;
  }

  // Punnett: resolve the two parent genotypes into aligned loci + traits.
  if (st.ast.mode === "punnett" && st.punnett && st.ast.punnett) {
    const sc = st.punnett;
    const loci1 = sc.p1raw ? parseGenotype(sc.p1raw) : null;
    const loci2 = sc.p2raw ? parseGenotype(sc.p2raw) : null;
    if (loci1 && loci2 && loci1.length > 0) {
      const genes: PunnettGene[] = loci1.map((l) => {
        const t = sc.traits[l.letter];
        return {
          dominant: l.letter,
          recessive: l.letter.toLowerCase(),
          ...(t?.dominant ? { dominantTrait: t.dominant } : {}),
          ...(t?.recessive ? { recessiveTrait: t.recessive } : {}),
        };
      });
      const parent1 = loci1.map((l) => [l.alleles[0], l.alleles[1]]);
      // align parent 2's loci to parent 1's order by locus letter
      const parent2 = genes.map((g) => {
        const found = loci2.find((l) => l.letter === g.dominant);
        return found ? [found.alleles[0], found.alleles[1]] : [g.dominant, g.recessive];
      });
      st.ast.punnett = { genes, parent1, parent2 };
      const dim = Math.pow(2, genes.length);
      st.ast.cols = dim;
      st.ast.rows = dim;
    }
  }

  return st.ast;
}

function findCommentStart(line: string): number {
  let inQuote: string | null = null;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]!;
    if (inQuote) {
      if (ch === inQuote) inQuote = null;
    } else if (ch === '"' || ch === "'") {
      inQuote = ch;
    } else if (ch === "#") {
      return i;
    }
  }
  return -1;
}

// also export for testing
export { DEFAULT_CONFIG };
