/**
 * Gantt rendering for the PERT engine — `layout: gantt` (or the `gantt` header).
 *
 * Spec: docs/reference/32-PERT-STANDARD.md §9.5.
 *
 * The differentiator: unlike a hand-placed Gantt (Mermaid), the bars are placed
 * from the *computed* schedule — `schedulePert` runs the forward/backward pass,
 * so ES/EF and the critical path are derived from the dependency graph, not
 * typed in. This module is the calendar + bar-chart presentation of that
 * schedule: one row per task, sections by `lane:`, a date axis (when `start:` is
 * given), critical-path bars in red, milestones as diamonds, progress overlays,
 * dependency connectors, and an optional "today" marker.
 *
 * Calendar handling is pure integer arithmetic (days-from-civil, Howard
 * Hinnant) so it is deterministic and dependency-free. `calendar: 5day` excludes
 * weekends from the timeline (the axis labels skip Sat/Sun); bars stay
 * contiguous in working time.
 */

import type { RenderConfig } from "../../core/types";
import {
  svgRoot,
  group,
  el,
  rect,
  line,
  path as pathEl,
  polygon,
  text as textEl,
  title as titleEl,
  desc,
  escapeXml,
} from "../../core/svg";
import { resolveBaseTheme } from "../../core/theme";
import type { PertAst, PertScheduleResult, PertTask } from "./types";

interface GanttPalette {
  bar: string;
  barStroke: string;
  barDone: string;
  critBar: string;
  critStroke: string;
  critDone: string;
  milestone: string;
  text: string;
  subtext: string;
  axis: string;
  grid: string;
  sectionBand: string;
  sectionText: string;
  dep: string;
  today: string;
}

const PALETTES: Record<string, GanttPalette> = {
  default: {
    bar: "#cfe0f5", barStroke: "#5b85c0", barDone: "#5b85c0",
    critBar: "#fbe6e0", critStroke: "#d2604f", critDone: "#d2604f",
    milestone: "#3c5a80", text: "#234567", subtext: "#728198",
    axis: "#8497ad", grid: "#e3eaf3", sectionBand: "#eef3fa",
    sectionText: "#41597a", dep: "#9fb0c6", today: "#d2604f",
  },
  monochrome: {
    bar: "#ffffff", barStroke: "#000000", barDone: "#9a9a9a",
    critBar: "#ffffff", critStroke: "#000000", critDone: "#000000",
    milestone: "#000000", text: "#000000", subtext: "#555555",
    axis: "#000000", grid: "#dddddd", sectionBand: "#f2f2f2",
    sectionText: "#000000", dep: "#888888", today: "#000000",
  },
  dark: {
    bar: "#37506e", barStroke: "#89b4fa", barDone: "#89b4fa",
    critBar: "#5a3540", critStroke: "#f38ba8", critDone: "#f38ba8",
    milestone: "#bac2de", text: "#cdd6f4", subtext: "#9399b2",
    axis: "#7f849c", grid: "#313244", sectionBand: "#272838",
    sectionText: "#bac2de", dep: "#6c7086", today: "#f38ba8",
  },
};

// ─── Calendar (days-from-civil, integer, deterministic) ────────────

/** Days since 1970-01-01 for a Gregorian y-m-d (Hinnant's algorithm). */
function ymdToDays(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor((yy >= 0 ? yy : yy - 399) / 400);
  const yoe = yy - era * 400;
  const doy = Math.floor((153 * (m > 2 ? m - 3 : m + 9) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function daysToYmd(z: number): { y: number; m: number; d: number } {
  const zz = z + 719468;
  const era = Math.floor((zz >= 0 ? zz : zz - 146096) / 146097);
  const doe = zz - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp < 10 ? mp + 3 : mp - 9;
  return { y: m <= 2 ? y + 1 : y, m, d };
}

function parseISODays(s: string): number {
  const [y, m, d] = s.split("-").map(Number);
  return ymdToDays(y!, m!, d!);
}

/** 0 = Sunday … 6 = Saturday (1970-01-01 was a Thursday = 4). */
function dow(days: number): number {
  return ((days % 7) + 4 + 7000) % 7;
}

function isWeekend(days: number): boolean {
  const w = dow(days);
  return w === 0 || w === 6;
}

/** Advance `n` working days (skipping weekends) from a calendar day number. */
function advanceWorking(startDays: number, n: number): number {
  let cur = startDays;
  let left = Math.round(n);
  const step = left >= 0 ? 1 : -1;
  left = Math.abs(left);
  while (left > 0) {
    cur += step;
    if (!isWeekend(cur)) left--;
  }
  return cur;
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function fmtDate(days: number): string {
  const { m, d } = daysToYmd(days);
  return `${MONTHS[m - 1]} ${d}`;
}

// ─── Layout constants ──────────────────────────────────────────────

const G = {
  PAD: 20,
  TITLE_H: 30,
  AXIS_H: 26,
  ROW_H: 28,
  BAR_H: 15,
  SECTION_H: 24,
  LABEL_MIN: 120,
  LABEL_MAX: 250,
  CHAR_W: 6.6,
  LABEL_PAD: 12,
  TARGET_CHART_W: 740,
  MIN_PX_UNIT: 5,
  MAX_PX_UNIT: 56,
  FOOTER_H: 28,
} as const;

export function renderGantt(
  ast: PertAst,
  schedule: PertScheduleResult,
  config?: RenderConfig,
): string {
  const base = resolveBaseTheme(config?.theme ?? "default");
  const themeName = (config?.theme ?? "default") in PALETTES ? (config!.theme as string) : "default";
  const P = PALETTES[themeName]!;

  const tasks = ast.tasks;
  const span = Math.max(schedule.projectDuration, 1);
  const unitToDay = ast.unit === "weeks" ? 7 : 1; // continuous calendar
  const unitToWork = ast.unit === "weeks" ? 5 : 1; // 5day calendar

  // x-scale: fit the project into a target width, clamped for legibility.
  const pxUnit = Math.max(G.MIN_PX_UNIT, Math.min(G.MAX_PX_UNIT, G.TARGET_CHART_W / span));

  // Left label column width from the longest task label.
  const longest = tasks.reduce((mx, t) => Math.max(mx, (t.label ?? t.id).length), 4);
  const labelW = Math.max(G.LABEL_MIN, Math.min(G.LABEL_MAX, Math.ceil(longest * G.CHAR_W) + 2 * G.LABEL_PAD));

  const chartX = G.PAD + labelW + 8;
  const chartW = Math.ceil(span * pxUnit);
  const hasTitle = !!ast.title;
  const topY = G.PAD + (hasTitle ? G.TITLE_H : 0);
  const axisBottom = topY + G.AXIS_H;

  // ── Rows: tasks in declaration order, section header when lane changes ──
  interface Row { kind: "section" | "task"; y: number; h: number; task?: PertTask; label?: string }
  const rows: Row[] = [];
  let cursorY = axisBottom + 6;
  let lastLane: string | undefined = "�";
  for (const t of tasks) {
    const lane = t.lane;
    if (lane !== lastLane && lane !== undefined) {
      rows.push({ kind: "section", y: cursorY, h: G.SECTION_H, label: lane });
      cursorY += G.SECTION_H;
      lastLane = lane;
    } else if (lane === undefined) {
      lastLane = undefined;
    }
    rows.push({ kind: "task", y: cursorY, h: G.ROW_H, task: t });
    cursorY += G.ROW_H;
  }
  const chartBottom = cursorY;
  const totalH = chartBottom + G.FOOTER_H + G.PAD;
  const totalW = chartX + chartW + G.PAD;

  // ── Time mapping ──
  const startDays = ast.start ? parseISODays(ast.start) : undefined;
  const xAt = (unitOffset: number): number => chartX + unitOffset * pxUnit;
  const offsetToDate = (u: number): number | undefined => {
    if (startDays === undefined) return undefined;
    return ast.calendar === "5day"
      ? advanceWorking(startDays, u * unitToWork)
      : startDays + Math.round(u * unitToDay);
  };

  // ── Axis ticks ──
  const niceStep = (s: number): number => {
    const raw = s / 9;
    const candidates = [1, 2, 5, 7, 10, 14, 20, 25, 50, 100];
    for (const c of candidates) if (c >= raw) return c;
    return Math.ceil(raw / 50) * 50;
  };
  const step = niceStep(span);

  // ── Build SVG ──
  const styleBlock = el("style", {}, `
.sx-gantt-bg { fill: ${base.bg}; }
.sx-gantt-title { fill: ${P.text}; font-size: 15px; font-weight: 700; }
.sx-gantt-grid { stroke: ${P.grid}; stroke-width: 1; }
.sx-gantt-axis-tick { stroke: ${P.axis}; stroke-width: 1; }
.sx-gantt-axis-text { fill: ${P.subtext}; font-size: 9.5px; }
.sx-gantt-axis-base { stroke: ${P.axis}; stroke-width: 1.2; }
.sx-gantt-section { fill: ${P.sectionBand}; }
.sx-gantt-section-text { fill: ${P.sectionText}; font-size: 11px; font-weight: 700; }
.sx-gantt-rowlabel { fill: ${P.text}; font-size: 11.5px; }
.sx-gantt-rowlabel.crit { fill: ${P.critStroke}; font-weight: 600; }
.sx-gantt-bar { fill: ${P.bar}; stroke: ${P.barStroke}; stroke-width: 1; }
.sx-gantt-bar[data-critical="true"] { fill: ${P.critBar}; stroke: ${P.critStroke}; stroke-width: 1.4; }
.sx-gantt-done { fill: ${P.barDone}; }
.sx-gantt-done[data-critical="true"] { fill: ${P.critDone}; }
.sx-gantt-ms { fill: ${P.milestone}; stroke: ${P.milestone}; }
.sx-gantt-ms[data-critical="true"] { fill: ${P.critStroke}; stroke: ${P.critStroke}; }
.sx-gantt-dep { fill: none; stroke: ${P.dep}; stroke-width: 1; }
.sx-gantt-barlabel { fill: ${P.subtext}; font-size: 9.5px; }
.sx-gantt-today { stroke: ${P.today}; stroke-width: 1.3; stroke-dasharray: 4 3; }
.sx-gantt-today-text { fill: ${P.today}; font-size: 9.5px; font-weight: 700; }
.sx-gantt-footer { fill: ${P.subtext}; font-size: 10px; }
`.trim());

  const children: string[] = [
    titleEl(`Gantt chart${ast.title ? " — " + ast.title : ""}`),
    desc(summarise(ast, schedule)),
    styleBlock,
    rect({ x: 0, y: 0, width: totalW, height: totalH, class: "sx-gantt-bg" }),
  ];

  if (hasTitle) {
    children.push(textEl({ x: G.PAD, y: G.PAD + 18, class: "sx-gantt-title" }, ast.title!));
  }

  // Section bands (under everything in the chart).
  const bandEls: string[] = [];
  for (const r of rows) {
    if (r.kind === "section") {
      bandEls.push(rect({ x: G.PAD, y: r.y, width: totalW - 2 * G.PAD, height: r.h, class: "sx-gantt-section" }));
      bandEls.push(textEl({ x: G.PAD + 8, y: r.y + r.h / 2 + 4, class: "sx-gantt-section-text" }, r.label!));
    }
  }
  children.push(group({ class: "sx-gantt-sections" }, bandEls));

  // Grid + axis.
  const axisEls: string[] = [];
  for (let u = 0; u <= span + 0.0001; u += step) {
    const x = xAt(u);
    axisEls.push(line({ class: "sx-gantt-grid", x1: x, y1: axisBottom, x2: x, y2: chartBottom }));
    axisEls.push(line({ class: "sx-gantt-axis-tick", x1: x, y1: axisBottom - 5, x2: x, y2: axisBottom }));
    const cal = offsetToDate(u);
    const label = cal !== undefined ? fmtDate(cal) : fmtVal(u);
    axisEls.push(textEl({ x, y: axisBottom - 9, class: "sx-gantt-axis-text", "text-anchor": "middle" }, label));
  }
  axisEls.push(line({ class: "sx-gantt-axis-base", x1: chartX, y1: axisBottom, x2: chartX + chartW, y2: axisBottom }));
  children.push(group({ class: "sx-gantt-axis" }, axisEls));

  // Row labels.
  const labelEls: string[] = [];
  for (const r of rows) {
    if (r.kind !== "task" || !r.task) continue;
    const c = schedule.computed.get(r.task.id);
    const crit = c?.critical ?? false;
    labelEls.push(
      textEl(
        { x: G.PAD + 4, y: r.y + r.h / 2 + 4, class: `sx-gantt-rowlabel${crit ? " crit" : ""}` },
        clip(r.task.label ?? r.task.id, Math.floor(labelW / G.CHAR_W)),
      ),
    );
  }
  children.push(group({ class: "sx-gantt-rowlabels" }, labelEls));

  // Dependency connectors (FS-style elbows, under bars).
  const rowOf = new Map<string, Row>();
  for (const r of rows) if (r.kind === "task" && r.task) rowOf.set(r.task.id, r);
  const depEls: string[] = [];
  for (const t of tasks) {
    const tr = rowOf.get(t.id);
    const tc = schedule.computed.get(t.id);
    if (!tr || !tc) continue;
    const succMidY = tr.y + tr.h / 2;
    const succX = xAt(tc.es);
    for (const dep of t.deps) {
      const pr = rowOf.get(dep.pred);
      const pc = schedule.computed.get(dep.pred);
      if (!pr || !pc) continue;
      const predMidY = pr.y + pr.h / 2;
      const predX = xAt(pc.ef);
      const midX = Math.max(predX + 8, succX - 10);
      depEls.push(pathEl({
        class: "sx-gantt-dep",
        d: `M ${r1(predX)} ${r1(predMidY)} H ${r1(midX)} V ${r1(succMidY)} H ${r1(succX - 3)}`,
      }));
    }
  }
  children.push(group({ class: "sx-gantt-deps" }, depEls));

  // Bars / milestones.
  const barEls: string[] = [];
  for (const r of rows) {
    if (r.kind !== "task" || !r.task) continue;
    const t = r.task;
    const c = schedule.computed.get(t.id);
    if (!c) continue;
    const crit = c.critical;
    const cy = r.y + r.h / 2;
    if (t.milestone || t.duration === 0) {
      const x = xAt(c.es);
      const s = 7;
      barEls.push(group(
        { class: "sx-gantt-task", "data-id": t.id, "data-critical": String(crit), "data-es": String(c.es) },
        [polygon({
          class: "sx-gantt-ms", "data-critical": String(crit),
          points: `${r1(x)},${r1(cy - s)} ${r1(x + s)},${r1(cy)} ${r1(x)},${r1(cy + s)} ${r1(x - s)},${r1(cy)}`,
        })],
      ));
      continue;
    }
    const x = xAt(c.es);
    const w = Math.max(2, (c.ef - c.es) * pxUnit);
    const by = cy - G.BAR_H / 2;
    const parts: string[] = [
      rect({ x: r1(x), y: r1(by), width: r1(w), height: G.BAR_H, rx: 3, class: "sx-gantt-bar", "data-critical": String(crit) }),
    ];
    if (t.progress !== undefined && t.progress > 0) {
      parts.push(rect({
        x: r1(x), y: r1(by), width: r1(Math.max(2, (w * t.progress) / 100)), height: G.BAR_H, rx: 3,
        class: "sx-gantt-done", "data-critical": String(crit),
      }));
    }
    // Duration / slack caption to the right of the bar.
    const cap = c.slack > 0 ? `${fmtVal(c.ef - c.es)}${unitSuffix(ast.unit)} · slack ${fmtVal(c.slack)}` : `${fmtVal(c.ef - c.es)}${unitSuffix(ast.unit)}`;
    parts.push(textEl({ x: r1(x + w + 5), y: r1(cy + 3.5), class: "sx-gantt-barlabel" }, cap));
    barEls.push(group(
      {
        class: "sx-gantt-task", "data-id": t.id, "data-critical": String(crit),
        "data-es": String(c.es), "data-ef": String(c.ef), "data-slack": String(c.slack),
        ...(t.progress !== undefined ? { "data-progress": String(t.progress) } : {}),
      },
      parts,
    ));
  }
  children.push(group({ class: "sx-gantt-bars" }, barEls));

  // Today marker.
  if (ast.today && startDays !== undefined) {
    const todayDays = parseISODays(ast.today);
    let u: number;
    if (ast.calendar === "5day") {
      // Count working days between start and today.
      u = workingDaysBetween(startDays, todayDays) / unitToWork;
    } else {
      u = (todayDays - startDays) / unitToDay;
    }
    if (u >= 0 && u <= span) {
      const x = xAt(u);
      children.push(group({ class: "sx-gantt-today-g" }, [
        line({ class: "sx-gantt-today", x1: x, y1: axisBottom, x2: x, y2: chartBottom }),
        textEl({ x, y: chartBottom + 12, class: "sx-gantt-today-text", "text-anchor": "middle" }, "today"),
      ]));
    }
  }

  // Footer.
  const footer = `${schedule.order.length} tasks · duration ${fmtVal(schedule.projectDuration)}${unitSuffix(ast.unit)} · critical path: ${schedule.criticalPath.join(" → ") || "—"}`;
  children.push(textEl({ x: G.PAD, y: totalH - 10, class: "sx-gantt-footer" }, clip(footer, Math.floor((totalW - 2 * G.PAD) / 5.4))));

  return svgRoot(
    {
      class: "sx-gantt",
      role: "img",
      "aria-label": escapeXml(ast.title ?? "Gantt chart"),
      width: totalW,
      height: totalH,
      viewBox: `0 0 ${totalW} ${totalH}`,
      "data-diagram-type": "pert",
      "data-layout": "gantt",
    },
    children,
  );
}

// ─── Helpers ───────────────────────────────────────────────────────

function workingDaysBetween(a: number, b: number): number {
  if (b < a) return -workingDaysBetween(b, a);
  let n = 0;
  for (let d = a; d < b; d++) if (!isWeekend(d)) n++;
  return n;
}

function unitSuffix(unit: PertAst["unit"]): string {
  switch (unit) {
    case "days": return "d";
    case "weeks": return "w";
    case "hours": return "h";
    default: return "";
  }
}

function fmtVal(n: number): string {
  return String(parseFloat(n.toFixed(2)));
}

function r1(n: number): number {
  return Math.round(n * 10) / 10;
}

function clip(s: string, n: number): string {
  return s.length <= n ? s : s.slice(0, Math.max(1, n - 1)) + "…";
}

function summarise(ast: PertAst, s: PertScheduleResult): string {
  const parts = [`Gantt chart: ${s.order.length} tasks, project duration ${fmtVal(s.projectDuration)}${unitSuffix(ast.unit)}.`];
  if (ast.start) parts.push(`Starts ${ast.start} (${ast.calendar === "5day" ? "weekdays only" : "continuous"}).`);
  if (s.criticalPath.length) parts.push(`Critical path: ${s.criticalPath.join(" → ")}.`);
  return parts.join(" ");
}
